create table gov_repo.constitution_registry(const_id uuid primary key default uuid_generate_v4(),const_code varchar(20) not null,const_name varchar(255) not null,version varchar(20) not null,status varchar(30) not null default 'draft',governing_question text not null,content_md text,content_hash char(64),ratified_by uuid references gov_repo.governance_users(user_id),ratified_at timestamptz,superseded_by uuid references gov_repo.constitution_registry(const_id),organisation_id uuid not null references gov_repo.organisations(organisation_id),ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint constitution_registry_code_version_unique unique(const_code,version));
create table gov_repo.rfc_registry(rfc_id uuid primary key default uuid_generate_v4(),rfc_code varchar(30) not null,title varchar(255) not null,summary text not null,affected_cf varchar(20)[],rfc_type varchar(30) not null,status varchar(30) not null default 'draft',author_id uuid not null references gov_repo.governance_users(user_id),content_md text,discussion_log jsonb not null default '[]',votes_for integer not null default 0,votes_against integer not null default 0,votes_abstain integer not null default 0,voting_deadline timestamptz,outcome text,implemented_in varchar(20),organisation_id uuid not null references gov_repo.organisations(organisation_id),ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint rfc_registry_code_unique unique(rfc_code));
create table gov_repo.appeals(appeal_id uuid primary key default uuid_generate_v4(),appeal_code varchar(30) not null,title varchar(255) not null,description text not null,subject_type varchar(50) not null,subject_id uuid not null,grounds text not null,appellant_id uuid not null references gov_repo.governance_users(user_id),status varchar(30) not null default 'submitted',reviewer_id uuid references gov_repo.governance_users(user_id),reviewed_at timestamptz,decision text,decision_rationale text,remedy text,organisation_id uuid not null references gov_repo.organisations(organisation_id),ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint appeals_code_unique unique(appeal_code));
create table gov_repo.council_decisions(decision_id uuid primary key default uuid_generate_v4(),decision_code varchar(30) not null,title varchar(255) not null,summary text not null,subject_type varchar(50),subject_id uuid,decision_type varchar(30) not null,ruling text not null,rationale text not null,decided_by uuid[] not null,majority_percent numeric(5,2),dissenting_opinions jsonb default '[]',effective_date date not null,status varchar(30) not null default 'active',overturned_by uuid references gov_repo.council_decisions(decision_id),organisation_id uuid not null references gov_repo.organisations(organisation_id),ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence),created_at timestamptz not null default now(),constraint council_decisions_code_unique unique(decision_code));
create table gov_repo.amendments(amendment_id uuid primary key default uuid_generate_v4(),amendment_code varchar(30) not null,title varchar(255) not null,description text not null,rfc_id uuid references gov_repo.rfc_registry(rfc_id),affected_cf varchar(20) not null,change_type varchar(30) not null,change_summary text not null,old_text text,new_text text not null,ratified_by uuid not null references gov_repo.governance_users(user_id),council_decision_id uuid references gov_repo.council_decisions(decision_id),effective_date date not null,status varchar(30) not null default 'ratified',superseded_by uuid references gov_repo.amendments(amendment_id),organisation_id uuid not null references gov_repo.organisations(organisation_id),ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence),created_at timestamptz not null default now(),constraint amendments_code_unique unique(amendment_code));
alter table gov_repo.constitution_registry enable row level security;alter table gov_repo.rfc_registry enable row level security;alter table gov_repo.appeals enable row level security;alter table gov_repo.council_decisions enable row level security;alter table gov_repo.amendments enable row level security;;
